import{_ as t,o as h,c as a,a2 as e}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"Learner Model","description":"","frontmatter":{},"headers":[],"relativePath":"learner/learner-model.md","filePath":"learner/learner-model.md"}'),c={name:"learner/learner-model.md"};function g(i,n,o,r,l,u){return h(),a("div",null,[...n[0]||(n[0]=[e('<h1 id="learner-model" tabindex="-1">Learner Model <a class="header-anchor" href="#learner-model" aria-label="Permalink to &quot;Learner Model&quot;">​</a></h1><p>Trên trang này# Learner Model <a href="#learner-model">​</a> Learner Model là bức tranh có cấu trúc mà hệ thống dựng về một learner: con đang ở đâu trên từng mảng kiến thức, học theo kiểu nào, và — quan trọng không kém — hệ thống chắc chắn tới đâu về mỗi điều đó. Nó <strong>không phải</strong> hồ sơ học bạ. Học bạ ghi lại quá khứ. Learner Model là <strong>trạng thái được tính lại liên tục</strong> từ toàn bộ bằng chứng hiện có, và nó thay đổi mỗi khi có bằng chứng mới.</p><h2 id="trong-đo-co-gi-​" tabindex="-1">Trong đó có gì <a href="#trong-đo-co-gi">​</a> <a class="header-anchor" href="#trong-đo-co-gi-​" aria-label="Permalink to &quot;Trong đó có gì [​](#trong-đo-co-gi)&quot;">​</a></h2><p>textLearner Model ├── Identity — tuổi, lớp, trường, ngôn ngữ ├── Academic State — từng mảng kiến thức: mức vững + độ chắc chắn + xu hướng ├── Capability State — kỹ năng xuyên môn: lập luận, đọc hiểu, giải quyết vấn đề ├── Learning Characteristics — học nhanh hay chậm, cần bao nhiêu lần lặp, hợp cách nào ├── Behavioral Patterns — bỏ cuộc khi nào, làm bài lúc nào, dùng gợi ý ra sao ├── Preferences — thích dạng bài nào, tự chọn học gì khi được chọn └── Goals — đang hướng tới điều gì (có thể để trống)Phần được dùng nhiều nhất là <strong>Academic State</strong>. Kiến thức được tổ chức thành một mạng lưới các node — &quot;phân tích đa thức&quot;, &quot;tam giác đồng dạng&quot;, &quot;thì hiện tại hoàn thành&quot; — và mỗi node mang một bộ số: text{ mastery: 0.72 — mức vững quan sát được confidence: 0.45 — hệ thống tin vào con số trên tới đâu trajectory: đang lên — xu hướng gần đây last_evidence_at: 12 ngày trước evidence_count: 7 }</p><h2 id="mastery-va-confidence-la-hai-chuyen-khac-nhau-​" tabindex="-1">Mastery và confidence là hai chuyện khác nhau <a href="#mastery-va-confidence-la-hai-chuyen-khac-nhau">​</a> <a class="header-anchor" href="#mastery-va-confidence-la-hai-chuyen-khac-nhau-​" aria-label="Permalink to &quot;Mastery và confidence là hai chuyện khác nhau [​](#mastery-va-confidence-la-hai-chuyen-khac-nhau)&quot;">​</a></h2><p>Đây là phân biệt quan trọng nhất trong cả Learner Model. mastery 0.85 · confidence 0.20&quot;Có vẻ con giỏi phần này, nhưng tôi mới thấy hai câu, cùng một dạng, làm cách đây một tháng. Tôi chưa dám chắc.&quot; mastery 0.85 · confidence 0.90&quot;Con vững phần này. Tôi đã thấy 14 bằng chứng, nhiều dạng khác nhau, nhiều thời điểm, kết quả nhất quán.&quot; Hai learner có cùng con số 0.85 nhưng cần hai hành động hoàn toàn khác nhau: trường hợp đầu cần <strong>đo thêm</strong>, trường hợp sau có thể <strong>đi tiếp</strong>. Một hệ thống chỉ lưu mỗi mastery sẽ đối xử với hai em này giống hệt nhau. <a href="/learner/confidence">Đọc kỹ hơn về Confidence Score →</a></p><h2 id="mot-cau-đung-khong-lam-muc-vung-nhay-vot-​" tabindex="-1">Một câu đúng không làm mức vững nhảy vọt <a href="#mot-cau-đung-khong-lam-muc-vung-nhay-vot">​</a> <a class="header-anchor" href="#mot-cau-đung-khong-lam-muc-vung-nhay-vot-​" aria-label="Permalink to &quot;Một câu đúng không làm mức vững nhảy vọt [​](#mot-cau-đung-khong-lam-muc-vung-nhay-vot)&quot;">​</a></h2><p>Mỗi bằng chứng mới đẩy mức vững đi một đoạn, và độ dài đoạn đó phụ thuộc vào <strong>chất lượng của bằng chứng</strong>: textsức nặng của bằng chứng = độ tin cậy của nguồn × độ mới (bằng chứng cũ nhẹ hơn) × độ khó của bài × mức độ tự làm (có gợi ý thì nhẹ hơn)Ví dụ thật: learner đang ở 0.60, làm một bài khó và đúng hoàn toàn không gợi ý → mức vững lên 0.69. Không phải 0.90. Một lần làm tốt là bằng chứng thật, nhưng nó không xoá được mọi thứ hệ thống đã quan sát trước đó. Chiều ngược lại cũng vậy: một câu sai không đánh sập một node đang vững. Nếu learner có 12 bằng chứng tốt rồi sai một câu, hệ thống ghi nhận nhưng không kết luận lại — nó chờ xem đó là dấu hiệu thật hay chỉ là một ngày tệ.</p><h2 id="mastery-khong-tu-giam-theo-thoi-gian-​" tabindex="-1">Mastery không tự giảm theo thời gian <a href="#mastery-khong-tu-giam-theo-thoi-gian">​</a> <a class="header-anchor" href="#mastery-khong-tu-giam-theo-thoi-gian-​" aria-label="Permalink to &quot;Mastery không tự giảm theo thời gian [​](#mastery-khong-tu-giam-theo-thoi-gian)&quot;">​</a></h2><p>Đây là quy tắc kiến trúc mà Nemo12 giữ nghiêm ngặt: <strong>mức vững đã đạt thì không bị trừ dần vì lâu không dùng</strong>. Nếu learner từng đạt 0.90 và ba tháng không đụng tới, hệ thống <strong>không</strong> hạ nó xuống 0.64. Con số 0.90 giữ nguyên — vì nó là sự thật lịch sử: đã có lúc con làm được ở mức đó. Cái thay đổi là một con số <strong>riêng biệt</strong>: khả năng con còn nhớ và dùng được ngay lúc này. Việc tách hai chiều đo này cho phép phân biệt hai tình huống mà bề ngoài giống hệt nhau:</p><ul><li><strong>Từng vững, giờ mờ</strong> → cần đánh thức trí nhớ, một hai câu là đủ.</li><li><strong>Chưa từng vững</strong> → cần học lại thật sự, từ đầu. Đối xử với trường hợp đầu như trường hợp sau là cách lãng phí thời gian phổ biến nhất trong việc ôn tập. <a href="/decisions/retention">Đọc về retention →</a></li></ul><h2 id="model-co-phien-ban-​" tabindex="-1">Model có phiên bản <a href="#model-co-phien-ban">​</a> <a class="header-anchor" href="#model-co-phien-ban-​" aria-label="Permalink to &quot;Model có phiên bản [​](#model-co-phien-ban)&quot;">​</a></h2><p>Mỗi lần Learner Model được tính lại, hệ thống ghi kèm: tính lúc nào, dựa trên bằng chứng tới đâu, bằng thuật toán phiên bản nào. Nhờ vậy khi một gợi ý hôm nay khác hôm qua, luôn trả lời được <strong>vì sao khác</strong> — và nếu thuật toán được cải tiến, toàn bộ lịch sử có thể tính lại từ bằng chứng gốc. Learner Model là giả thuyết tốt nhất hiện có về một đứa trẻ, kèm mức độ tin cậy — không phải bản án về đứa trẻ đó. <a href="/learner/context-model">Learner Context Model →</a></p>',13)])])}const d=t(c,[["render",g]]);export{s as __pageData,d as default};
